// @vitest-environment jsdom
import React from 'react';
import {describe, it, expect} from 'vitest';
import {render, fireEvent, cleanup} from '@testing-library/react';
import {ThemeProvider} from '@gravity-ui/uikit';
import {App} from './App';

const mount = () => render(<ThemeProvider theme="light"><App /></ThemeProvider>);

describe('dashboard', () => {
  it('renders nav, grouped table, selection, ungroup', () => {
    const {container, getByText} = mount();
    for (const t of ['Главная', 'Пользователи', 'Заказы', 'Настройки']) expect(container.textContent).toContain(t);
    const heads = [...container.querySelectorAll('thead th')].map((h) => h.textContent);
    console.log('HEADS', heads);
    const rows = container.querySelectorAll('tbody tr');
    console.log('rows grouped', rows.length, rows[0].textContent);
    const boxes = container.querySelectorAll('tbody input[type=checkbox]');
    console.log('row checkboxes', boxes.length);
    fireEvent.click(boxes[0]);
    console.log('after select:', container.textContent!.match(/Выбрано: \d+ из \d+/)?.[0]);
    // toggle off grouping
    fireEvent.click(container.querySelector('.g-switch input')!);
    const rows2 = container.querySelectorAll('tbody tr');
    console.log('rows flat', rows2.length, container.textContent!.match(/Выбрано: \d+ из \d+/)?.[0]);
    // select all via header
    fireEvent.click(container.querySelector('thead input[type=checkbox]')!);
    console.log('after all:', container.textContent!.match(/Выбрано: \d+ из \d+/)?.[0]);
    cleanup();
  });
});
EOF
