// @vitest-environment jsdom
import React from 'react';
import {it, expect} from 'vitest';
import {render, fireEvent} from '@testing-library/react';
import {ThemeProvider} from '@gravity-ui/uikit';
import {App} from './App';

it('collapse group + compact sidebar', () => {
  const {container} = render(<ThemeProvider theme="light"><App /></ThemeProvider>);
  const before = container.querySelectorAll('tbody tr').length;
  fireEvent.click(container.querySelector('tbody tr button')!);
  console.log('rows before/after group collapse', before, container.querySelectorAll('tbody tr').length);
  const btn = [...container.querySelectorAll('button')].find((b) => /Свернуть|Collapse|Expand|Развернуть/i.test(b.getAttribute('aria-label') ?? b.title ?? ''));
  console.log('collapse btn', btn?.getAttribute('aria-label'));
  fireEvent.click(btn!);
  console.log('compact stored', localStorage.getItem('admin:sidebar-compact'));
});
EOF
